captured_statement:
SELECT id AS id, event_ts AS event_ts, amount AS amount, qty AS qty, status AS status, country AS country, category AS category, name AS name 
FROM bi_events GROUP BY id, event_ts, amount, qty, status, country, category, name
 LIMIT 100;

SELECT category AS category, sum(amount) AS "SUM(amount)" 
FROM bi_events GROUP BY category ORDER BY "SUM(amount)" DESC
 LIMIT 10000;

SELECT event_ts AS event_ts, AVG(amount) AS "AVG(amount)" 
FROM bi_events GROUP BY event_ts
 LIMIT 10000;

SELECT UPPER(country) AS upper_country, SUBSTRING(name, 1, 3) AS name_prefix, MAX(LENGTH(name)) AS max_name_len, sum(amount) AS "SUM(amount)" 
FROM bi_events GROUP BY UPPER(country), SUBSTRING(name, 1, 3)
 LIMIT 10000;
